        new("SCRIPTS-TYPE-0013", "type", Severity.Error, "wrong number of arguments for `{function}`: expected {expected}, got {found}", "no optional or variadic arguments: named arguments exist, but the number of arguments MUST still equal that of the parameters.", "call `{signature}`", "the first extra argument, or the closing parenthesis if some are missing", "active"),
        new("SCRIPTS-TYPE-0014", "type", Severity.Error, "the value of type `{type}` is not callable", "only function names, module members and values of function type are called", "remove the parentheses, or call a function", "the called expression", "active"),
        new("SCRIPTS-TYPE-0015", "type", Severity.Error, "operator `{operator}` not defined for the types `{left}` and `{right}`", "the operator does not exist for the type of the left operand (for example `path + path`, `boolean + boolean`, `1 and true`, `true + 1`); if `left op left` is defined but the right type differs, it is `SCRIPTS-TYPE-0016`", "operators defined for these types: {supported} (for a path: `path / \"segment\"`)", "the operator", "active"),
        new("SCRIPTS-TYPE-0016", "type", Severity.Error, "operands of different types for `{operator}`: `{left}` and `{right}`", "the two operands have different types while the operator is defined for the left type with an operand of the same type (`1 + 1.5`, `\"a\" + 1`, `1 == \"a\"`, `p\"a\" / 1`); no implicit mixing of `integer` and `float` (or of other types) is allowed", "convert an operand: `to_float(…)` or `to_integer(…)`", "the operator", "active"),
        new("SCRIPTS-TYPE-0017", "type", Severity.Error, "unary operator `{operator}` not defined for the type `{type}`", "`-` applies to `integer`/`float`; `not` applies to `boolean`", "use an operand of type {supported}", "the operator", "active"),
        new("SCRIPTS-TYPE-0018", "type", Severity.Error, "comparison `{operator}` impossible on the type `{type}`", "`==` and `!=` are forbidden on `result`, functions, records, errors and `unit`, and on any `list<T>`/`map<K,V>` whose component type (at any depth) is forbidden (e.g. `list<result<integer, string>>`); the same composition criterion applies to `contains`", "compare parts: `.is_ok()`, a field (`.exit_code`), or use a `match`", "the operator", "active"),
        new("SCRIPTS-TYPE-0019", "type", Severity.Error, "order comparison `{operator}` impossible on the type `{type}`", "`< <= > >=` exist only for `integer`, `float`, `string` and `path`", "compare with `==`/`!=`, or convert to an ordered type", "the operator", "active"),
        new("SCRIPTS-TYPE-0020", "type", Severity.Error, "condition of type `{found}`: `boolean` expected", "the conditions of `if` and `while` MUST be `boolean` (no « truthiness »)", "write an explicit comparison (`n != 0`, `s.length() > 0`)", "the condition", "active"),
        new("SCRIPTS-TYPE-0021", "type", Severity.Error, "invalid compound assignment `{operator}`: `{left} {op} {right}` is not defined or does not have the type `{left}`", "`x op= e` requires that `x op e` be defined and of the same type as `x`", "fix the type of `e`, or convert (`to_float`, interpolation) before the operation", "the compound assignment operator", "active"),
        new("SCRIPTS-TYPE-0022", "type", Severity.Error, "`for` expects a list, got `{found}`", "`for x in e` iterates only over `list<T>`; a map is iterated by its keys", "for a map: `for k in m.keys()`; for a counter: `range(a, b)`", "the iterated expression", "active"),
        new("SCRIPTS-TYPE-0023", "type", Severity.Error, "the type `{type}` cannot be interpolated in a string", "only `string`, `integer`, `float`, `boolean` and `path` are interpolable", "convert to text first (`.join(\",\")` for a `list<string>`, `match` for a `result`)", "the interpolated expression", "active"),
        new("SCRIPTS-TYPE-0024", "type", Severity.Error, "`match` on a value of type `{type}` not allowed", "the allowed scrutinees are `integer`, `string`, `boolean` and `result<T,E>` (neither `float`, `path`, list, map)", "compare with `==` in `if`s, or convert the value", "the scrutinee expression", "active"),
        new("SCRIPTS-TYPE-0025", "type", Severity.Error, "pattern of type `{found}` incompatible with the scrutinee of type `{expected}`", "a literal, `ok(x)` or `error(x)` does not match the scrutinee type", "use a pattern of type `{expected}`", "the pattern", "active"),
        new("SCRIPTS-TYPE-0026", "type", Severity.Error, "non-exhaustive `match`: {missing}", "exhaustiveness is mandatory (`boolean`: `true` and `false` or a wildcard; `result`: `ok(_)` and `error(_)` or a wildcard; a closed `kind` set (`describe.types[].kinds`): every value or a wildcard; `integer`/`string`: a wildcard or a binding)", "cover every listed value or add a `_ => …` arm", "the `match` keyword", "active"),
        new("SCRIPTS-TYPE-0027", "type", Severity.Error, "unreachable arm: {reason}", "an arm placed after a wildcard or a catch-all binding, or repeating an already covered pattern (duplicate in an alternative included), can never be chosen", "remove this arm, or place it before the general arm", "the pattern of the unreachable arm", "active"),
        new("SCRIPTS-TYPE-0028", "type", Severity.Error, "the arms of the `match` have different types: `{first}` then `{found}`", "in expression position, all the arms are expressions of the same type", "give the same type to all the arms (convert if needed)", "the expression of the faulty arm", "active"),
        new("SCRIPTS-TYPE-0029", "type", Severity.Error, "undetermined type for `{expression}`: no expected type ({context})", "`[]`, `{}`, `ok()`, `ok(e)`, `error(e)` (and `fold([], …)`) need a complete expected type for the missing part ({context})", "annotate the type: `let xs: {suggested_type} = …`", "the expression with the undetermined type", "active"),
        new("SCRIPTS-TYPE-0030", "type", Severity.Error, "lambda without an expected type: parameter annotation mandatory", "`x => e` is valid only if a function type is expected by the context", "write `(x: T) => …`, or pass the lambda to a parameter of function type", "the start of the lambda", "active"),
        new("SCRIPTS-TYPE-0031", "type", Severity.Error, "lambda passed to a parameter of type `{expected}` (non-function)", "a lambda can be supplied only to a parameter of function type", "pass a value of type `{expected}`", "the start of the lambda", "active"),
        new("SCRIPTS-TYPE-0032", "type", Severity.Error, "the lambda has {found} parameter(s), {expected} expected", "the number of parameters of the lambda differs from that of the expected function type", "write a lambda with {expected} parameter(s)", "the start of the lambda", "active"),
        new("SCRIPTS-TYPE-0033", "type", Severity.Error, "`ok()` without an argument is valid only for `result<unit, E>` (expected: `{expected}`)", "`ok()` builds a `unit` result; the expected type is not `result<unit, E>`", "write `ok(value)`, or declare the type `result<unit, E>`", "the call `ok()`", "active"),
        new("SCRIPTS-TYPE-0034", "type", Severity.Error, "a `unit` value can neither be bound, nor stored, nor used as a type argument{context}", "`unit` cannot be bound by `let` (even `let _ =`), be an element of `list`/`map` or a type argument, except in `result<unit, E>`; the operand of `?` may unwrap to `unit` when the result is `result<unit, E>`", "call the expression as a statement, without `let` (for example `f()?`)", "the expression of type `unit` (or, for a type written `list<unit>`, `map<K, unit>`…, the word `unit` of the type)", "active"),
        new("SCRIPTS-TYPE-0035", "type", Severity.Error, "invalid map key type: `{type}`", "the keys of `map<K,V>` are `string`, `integer`, `path` or `boolean`", "use `string` (for example the text of the number by interpolation)", "the type of the key", "active"),
        new("SCRIPTS-TYPE-0036", "type", Severity.Error, "unknown type `{name}`", "no type of this name (no user types in 0.1.0)", "types: string integer float boolean path unit list<T> map<K,V> result<T,E> function(…) -> R process_result pipeline_result path_status file_system_status system_information process_handle directory_entry walk_report walk_skip run_request json_value file_lock error", "the type name", "active"),
        new("SCRIPTS-TYPE-0037", "type", Severity.Error, "wrong number of type arguments for `{type}`: expected {expected}, got {found}", "`list<T>` takes 1, `map<K,V>` and `result<T,E>` take 2, the other types none", "write `{usage}`", "the faulty type", "active"),
        new("SCRIPTS-TYPE-0038", "type", Severity.Error, "the type `never` cannot be written", "`never` is the type of `process.exit_with_code`; it is not writable by the user", "write `unit` or a value type", "the word `never`", "active"),
        new("SCRIPTS-TYPE-0039", "type", Severity.Error, "assignment to `{name}`: immutable variable", "only `let mutable` variables are reassignable; constants, parameters, `for` variables and pattern bindings are immutable; also applies to `name[index] = …` (modifying an element requires a `let mutable` variable)", "declare `let mutable {name} = …`", "the assigned name", "active"),
        new("SCRIPTS-TYPE-0040", "type", Severity.Error, "assignment impossible: `{name}` is not a variable", "`{name}` denotes a function, a module alias or an intrinsic namespace", "assign to a `let mutable` variable", "the assigned name", "active"),
        new("SCRIPTS-TYPE-0041", "type", Severity.Error, "the type `{type}` is not indexable", "only lists (`integer` index) and maps (`K` key) are indexed with `[…]`", "use the methods of the type `{type}`", "the indexed expression", "active"),
        new("SCRIPTS-TYPE-0042", "type", Severity.Error, "the mutating method `{method}` requires an identifier as receiver (not `{receiver}`)", "`append`, `insert_at`, `remove_at` and `remove_key` modify a variable: `m[\"k\"].append(1)`, `f().append(1)` and `xs.filter(is_correct).append(1)` are rejected", "copy into a mutable temporary variable: `let mutable tmp = …` then `tmp.{method}(…)`", "the receiver expression", "active"),
        new("SCRIPTS-TYPE-0043", "type", Severity.Error, "the mutating method `{method}` requires a `let mutable` variable: `{name}` is immutable", "the receiver of a mutating method MUST be bound by `let mutable`", "declare `let mutable {name} = …`", "the name of the receiver", "active"),
        new("SCRIPTS-TYPE-0044", "type", Severity.Error, "`?` forbidden in a lambda", "`?` returns from the current function; a lambda has no `result` return type of its own", "use `.collect()` on a `list<result<T,E>>` (`transform(…).collect()`), `match` or `.value_or(…)` in the lambda, or a named function that returns a `result`", "the `?`", "active"),
        new("SCRIPTS-TYPE-0045", "type", Severity.Error, "`?` applied to a value of type `{found}`: a `result<T, E>` is required", "the `?` operator applies only to a `result`", "remove the `?`", "the `?`", "active"),
        new("SCRIPTS-TYPE-0046", "type", Severity.Error, "the error type `{found}` of `?` is incompatible with the return of the function `{function}` (`{expected}`)", "`e?` returns `error(x)`: the function MUST return `result<_, E>` with the same `E` (a `unit` function cannot use `?`)", "convert with `.transform_error(e => …)` before `?`, or declare `-> result<…, {found}>`", "the `?`", "active"),
        new("SCRIPTS-TYPE-0047", "type", Severity.Error, "top-level error of type `{found}`: a predefined error type or `string` is required", "at the top level, `error(x)` terminates the script (`SCRIPTS-RUNTIME-0017`) and `E` MUST be `error` or `string`", "convert with `.transform_error(e => …)` to `string`", "the `?`", "active"),
        new("SCRIPTS-TYPE-0048", "type", Severity.Error, "ignored value: the statement produces `{found}` instead of `unit`", "an expression-statement (including a `match` arm in statement position) MUST have the type `unit` (or `never`); silently ignoring a value is forbidden", "for a non-fallible value, write `let _ = {expression}` to discard explicitly; a fallible value must be propagated with `?` or handled", "the start of the statement", "active"),
        new("SCRIPTS-TYPE-0049", "type", Severity.Error, "`{name}` contains a `result` that is never read", "a variable (`let`, parameter, `for` variable, pattern binding or lambda parameter) whose type contains `result` and that is never read hides an ignored failure; \"read\" = appearing in an expression, outside an assignment target (`x = …`); names starting with `_` are exempt from this code, and a `_`/`_name` binding whose bound type contains `result` is checked by `SCRIPTS-TYPE-0070`", "handle the result (`match`, `?`, `.value_or(…)`), or read the binding; renaming a `_name` is not enough", "the name of the variable", "active"),
        new("SCRIPTS-TYPE-0050", "type", Severity.Error, "`{keyword}` outside a loop", "`break`/`continue` target the innermost loop of the same function; they are forbidden outside a loop, or in a nested function targeting an enclosing loop", "place `{keyword}` in a `while` or a `for` of the same function", "the keyword", "active"),
        new("SCRIPTS-TYPE-0051", "type", Severity.Error, "`return` without a value in a function that returns `{expected}`", "a function whose return type is not `unit` MUST return a value", "write `return value`", "the word `return`", "active"),
        new("SCRIPTS-TYPE-0052", "type", Severity.Error, "missing return: the function `{function}` must return `{expected}` on all paths", "a non-`unit` function MUST diverge on all paths (`return`, `process.exit_with_code`, complete `if/else`, exhaustive `match` with diverging arms, `while true` without `break`)", "add a `return` at the end of the function, or complete the `else`s", "the name of the function", "active"),
        new("SCRIPTS-TYPE-0053", "type", Severity.Error, "unreachable code after {statement}", "the statement follows a statement that always diverges (`return`, `process.exit_with_code`, complete diverging `if/else`, diverging `match`, `while true` without `break`)", "remove the statement, or place it before", "the start of the unreachable statement", "active"),
        new("SCRIPTS-TYPE-0054", "type", Severity.Error, "a top-level `return` cannot carry a value with no JSON rendering", "the value of the top-level `return` is exposed by `--json-out` and must be serializable; a function or an opaque `file_lock` has no JSON form", "return a serializable value, not a function or a `file_lock`", "the returned expression", "active"),
        new("SCRIPTS-TYPE-0055", "type", Severity.Error, "duplicate key `{key}` in the map literal (first occurrence at line {line})", "two constant keys with the same value in the same map literal (the dynamic case keeps the last value at the first position)", "remove or rename one of the keys", "the second occurrence of the key", "active"),
        new("SCRIPTS-TYPE-0056", "type", Severity.Error, "the standard function `{name}` cannot be used as a value", "only user function names serve as values; standard functions (global, `environment.*`, `io.*`, `process.*`, `json.*`, `filesystem.*`, `parallel.*`, `system.*`, `time.*`, `encoding.*`, `random.*`) are not values", "call the function with its arguments rather than passing it as a value; to pass it to a higher-order function, write a lambda whose parameters match those of the function and whose body is the call", "the name of the standard function", "active"),
        new("SCRIPTS-TYPE-0057", "type", Severity.Error, "the method `{method}` requires {constraint}: the receiver is of type `{type}`", "unsatisfied type constraint: `join` requires `list<string>`; `sorted`/`minimum`/`maximum` require `integer`, `float`, `string` or `path`; `contains` requires a type comparable by `==`; `sum` requires `list<integer>`; `collect` requires `list<result<T,E>>`", "convert the elements (for example with `.transform(…)`) before the call", "the name of the method", "active"),
        new("SCRIPTS-TYPE-0058", "type", Severity.Error, "value `{literal}` outside the set of `kind`s of `{error_type}` (values: {available})", "comparing a `kind` field (by `==`, `!=` or a `match` pattern) with a literal outside the closed set is almost always a typo", "fix: `{closest}`", "the literal", "active"),
        new("SCRIPTS-TYPE-0059", "type", Severity.Error, "`{name}` is a module, not a value", "an import alias or an intrinsic namespace is used only followed by `.member`", "call a member: `{name}.function(…)`", "the name of the module", "active"),
        new("SCRIPTS-TYPE-0060", "type", Severity.Error, "neither a visible function nor a method `{name}` for a pipeline on the type `{type}`", "`x |> f(a)` first looks for a visible function `f` (user or global standard; it always wins, even if its types do not fit, in which case the error is `SCRIPTS-TYPE-0012`), then the method `f` of `type(x)`; no candidate exists", "check the name; candidates: {available}", "the name of the stage", "reserved"),
        new("SCRIPTS-TYPE-0061", "type", Severity.Error, "`{name}.{member}(…)` in a pipeline: `{name}` is not a module", "a stage `NAME.NAME(…)` requires that the first name be an import alias or an intrinsic namespace", "(historical) there is no pipeline operator: write `f(x, a)` or `x.m(a)`; for a module, import it or use an intrinsic namespace", "the first name of the stage", "reserved"),
        new("SCRIPTS-TYPE-0062", "type", Severity.Error, "`error(kind, message, subject)`: `{literal}` is not a valid `kind` literal ({detail}; values: {available})", "the three-argument `error` constructor accepts only a string literal `kind` belonging to the closed set of the `error` type; a literal outside the set is a typo, and any other form (variable, interpolation, concatenation) prevents static checking", "fix: `{closest}`; write `error(\"not_found\", message, subject)` with a literal `kind` from the list", "the first argument (`kind`)", "active"),
        new("SCRIPTS-TYPE-0063", "type", Severity.Error, "the lambda passed to `parallel` mutates `{name}`: the workers share the captured variable", "the mutation `{method}` targets `{name}`, a mutable variable captured from outside the lambda; `parallel` runs the lambda on several workers and gives no shared-memory guarantee", "do not mutate a captured variable from the lambda; collect the returned values and mutate after the call, or run with `worker_count = 1`", "the captured variable name", "active"),
        new("SCRIPTS-TYPE-0064", "type", Severity.Error, "the receiver of `string.format_template` is an interpolated string: `{…}` is interpolation, not a `{N}` placeholder", "the receiver of `string.format_template` is a string literal that scripts interpolates (a normal `\"…\"`, not a raw `r\"…\"`); the text is computed before the method sees it, so a `{N}` placeholder would be an interpolation or would be silently ignored (`\"{name}\".format_template([values])` prints the name and drops `values`)", "write the receiver as a raw string (`r\"{0}\".format_template([values])`) — the only form that keeps `{N}` placeholders; a normal string interpolates its braces and cannot serve as a `{N}` template", "the start of the receiver literal", "active"),
        new("SCRIPTS-TYPE-0065", "type", Severity.Error, "empty literal separator in `{method}`: the call would fail at run time", "`split(\"\")` (or `split_regex(\"\")`) receives an empty literal separator: there is nothing to split on, so the call is a static mistake, not an environment failure. A non-literal `string` is not checked (it may be empty only for some runs: the fatal `SCRIPTS-RUNTIME-0008`/`invalid_argument` still applies then)", "pass a non-empty separator, or check the value at run time before the call", "the empty separator literal", "active"),
        new("SCRIPTS-TYPE-0066", "type", Severity.Error, "a `parallel` worker cannot use `{name}`: it may mutate captured state", "`parallel.transform` and `parallel.walk_directory` run their worker concurrently (`parallel.run_all` launches processes, it takes no worker function). A nested function (declared inside another function) can capture a `mutable` variable of its enclosing function and mutate it, and a function value can hold such a function; neither can be proven side-effect free, so a shared value could be observed mutated and the result would be nondeterministic. Inline lambdas are checked separately: a direct mutating method on a captured `mutable` is `SCRIPTS-TYPE-0063`.", "pass the value as a parameter instead of capturing it, or use a top-level function (it cannot see a script `mutable`, `SCRIPTS-TYPE-0007`)", "the nested function name, at the call or the worker argument", "active"),
        new("SCRIPTS-TYPE-0067", "type", Severity.Error, "invalid named arguments: {reason}", "a named call must name every parameter exactly once: a name that no parameter uses, a name given twice, or a parameter left unnamed is rejected; there are no default values", "check the parameter names with `scripts describe --name <qualified entry>` (for example `string.substring`) and name every one of them once", "the offending name, or the call when a parameter is missing", "active"),
        new("SCRIPTS-TYPE-0068", "type", Severity.Error, "the standard-library name `{old}` was renamed to {new}", "an earlier revision renamed the whole catalogue in place: one explicit name per intent, no alias and no compatibility layer; the old spelling is no longer reserved and does not resolve", "write {new}; `scripts check --fix` applies the rename when the replacement is a plain name", "the old name", "active"),
        new("SCRIPTS-TYPE-0069", "type", Severity.Error, "the right operand of `/` is `{value}`: a literal segment must be relative and non-empty", "`a / b` joins paths lexically and fails closed: a literal that starts with `/` would silently replace the base path, and a literal `\"\"`/`p\"\"` has no segment to add. The empty base stays legal with a non-empty relative segment (`p\"\" / \"x\"` is `p\"x\"`); a computed operand is checked at run time (`SCRIPTS-RUNTIME-0022`).", "drop the leading `/`, write a non-empty relative segment, or compute and check the segment before joining (`text.to_path()`)", "the literal", "active"),
        new("SCRIPTS-TYPE-0070", "type", Severity.Error, "`{name}` holds a fallible value that is discarded", "a `_` or `_name` binding whose bound type contains `result` must be read or consumed: it is never read, so an `error` would be erased. The rule covers `let` bindings, parameters, `for` variables and pattern bindings; `_` alone is unreadable, while a `_name` that is read later is accepted. `?` on a non-nested `result` removes the `result` from the bound type; a nested `result<result<…>>` still contains `result` and is rejected unless the binding is read.", "consume it with `?`, `match`, `require_success` (then `?`) or `value_or`, or read the `_name` binding to make the discard explicit", "the name of the binding", "active"),
        new("SCRIPTS-TYPE-0071", "type", Severity.Error, "`ignore_error` would discard a value of type `{type}`", "`ignore_error()` applies only to `result<unit, E>`: on any other result it would silently drop the computed value as well as the error", "keep the value with `.value_or(…)`, `?` or `match`", "the name of the method", "active"),
        new("SCRIPTS-TYPE-0072", "type", Severity.Error, "a block arm of a `match` expression must end with the value of the arm", "in a `match` used as a value, the last line of a `{ … }` arm is its value; this block ends with a statement", "add the value as the last line of the block, or move the statements out of the `match`", "the closing brace of the block", "active"),
        new("SCRIPTS-TYPE-0073", "type", Severity.Error, "`{keyword}` cannot leave a lambda", "a lambda body is a value computed later, possibly on another thread: a `return`, `break` or `continue` in one of its `match` block arms has no enclosing function or loop to leave", "make the arm produce a value, or turn the lambda into a named function", "the keyword", "active"),
        new("SCRIPTS-MODULE-0001", "module", Severity.Error, "module not found or unreadable: `{path}` ({reason})", "the imported file does not exist or is not a readable regular file (directory, permission denied, I/O error); content in invalid UTF-8 or too large falls under `SCRIPTS-PARSE-0001`/`-0004`; the path is relative to the directory of the importing file", "check the path relative to `{importer_directory}` and the file permissions", "the literal string of the import path", "active"),
        new("SCRIPTS-MODULE-0002", "module", Severity.Error, "import cycle: {cycle}", "a module imports, directly or not, a module being loaded (including the main script)", "extract the shared code into a third module imported by both", "the literal string of the import that closes the cycle (in the last file of the chain)", "active"),
        new("SCRIPTS-MODULE-0003", "module", Severity.Error, "maximum import depth exceeded (32) while importing `{path}`", "the import chain counts more than 32 levels below the main script", "flatten the module hierarchy", "the literal string of the import that exceeds the limit", "active"),
        new("SCRIPTS-MODULE-0004", "module", Severity.Error, "`{member}` is private in the module `{alias}`", "only the `public` entries of a module are accessible to the importer", "declare `public` in `{module_file}`, or do not use this member", "the name of the member", "active"),
        new("SCRIPTS-MODULE-0005", "module", Severity.Error, "the standard modules are intrinsic: `{name}` must not be imported", "an import string starting with `std:` does not designate an importable module; `environment`, `io`, `process`, `json`, `filesystem`, `parallel`, `system`, `time`, `encoding`, `random` and `csv` are intrinsic namespaces, reserved and always available without an import", "remove the import and call `io.*`, `process.*`, `json.*`, `filesystem.*`, `parallel.*`, `system.*`, `time.*`, `encoding.*`, `random.*` or `environment.*` directly; to import a local file, pass a relative `.scs` path", "the literal string of the import path", "active"),
        new("SCRIPTS-MODULE-0006", "module", Severity.Error, "the module `{alias}` does not define any member `{member}`", "the name is neither a function nor a constant of the module", "public members of `{alias}`: {available}", "the name of the member", "active"),
        new("SCRIPTS-MODULE-0007", "module", Severity.Error, "invalid import: `{path}` ({reason})", "the import path MUST be relative (neither absolute, nor empty, nor containing NUL), and every import requires an explicit `as <name>` alias (a declarable name: not a keyword, future-reserved word or reserved identifier)", "write `import \"relative/path.scs\" as alias`", "the literal string of the import path", "active"),
        new("SCRIPTS-MODULE-0008", "module", Severity.Error, "top-level statement forbidden in a module", "a module contains only `function` declarations and constant `let`s (apart from `import`): any other statement (call, assignment, `if`, `return`, …) is forbidden", "move the statement into a `public`/`private` function, or into the main script", "the start of the faulty statement (in the module)", "active"),
        new("SCRIPTS-MODULE-0009", "module", Severity.Error, "non-constant declaration forbidden in a module: `{name}` ({reason})", "in a module, a `let` MUST be immutable and have a constant initializer (literals, operators, earlier constants of the same file, `alias.CONSTANT`); no call, no `mutable`", "use a constant expression, or a function that computes the value", "the non-constant initializer, or the word `mutable`", "active"),
        new("SCRIPTS-MODULE-0010", "module", Severity.Error, "the function `{alias}.{member}` cannot be used as a value", "the access `alias.member` without a call is defined only for constants; module functions are called (conservative reading of §4.2)", "call `{alias}.{member}(…)` or wrap in a lambda: `x => {alias}.{member}(x)`", "the name of the member", "active"),
        new("SCRIPTS-RUNTIME-0001", "runtime", Severity.Error, "integer overflow: `{operation}`", "`+`, `-`, `*`, unary `-` of `-9223372036854775808`, `-9223372036854775808 / -1` or `-9223372036854775808 % -1` leaves the range of 64-bit integers (checked arithmetic)", "check the bounds before the operation, or work in `float` with `to_float`", "the start of the current statement", "active"),
