        new("SCRIPTS-RUNTIME-0005", "runtime", Severity.Error, "write index out of bounds: {index} for a list of length {length}", "`list[i] = v` with a nonexistent index (a list cannot be enlarged by assignment)", "use `.append(value)` to add at the end of the list", "the start of the current statement", "active"),
        new("SCRIPTS-RUNTIME-0006", "runtime", Severity.Error, "key missing from the map: {key}", "`map[k]` with a nonexistent key", "use `.get_value({key})` (`missing_key`) or `.contains_key({key})`", "the start of the current statement", "active"),
        new("SCRIPTS-RUNTIME-0007", "runtime", Severity.Error, "`value_or_fail` on an error: {error_description}", "`.value_or_fail()` called on an `error(…)`; `{error_description}` is the kind (closed set), the subject (context, empty if not applicable) and the message of the unified error, in the form « kind : subject : message » when the subject is present, « kind : message » otherwise (or the text for a `string` error)", "handle the error with `match`, `?` or `.value_or(value)`", "the start of the current statement", "active"),
        new("SCRIPTS-RUNTIME-0008", "runtime", Severity.Error, "empty separator in `split`", "`text.split(separator)` is called with an empty `separator` computed at run time (a variable, a parameter, a concatenation); an empty literal separator is rejected earlier, by `SCRIPTS-TYPE-0065`", "check the separator at run time before the call, or provide a non-empty one", "the start of the current statement", "active"),
        new("SCRIPTS-RUNTIME-0009", "runtime", Severity.Error, "empty search text in `replace`", "`text.replace(\"\", …)` is not defined", "provide a non-empty `search_text`", "the start of the current statement", "active"),
        new("SCRIPTS-RUNTIME-0010", "runtime", Severity.Error, "`range` too large: {count} elements (maximum 10000000)", "`range(a, b)` would produce more than 10 000 000 elements", "iterate in chunks, or use a `while` with a counter", "the start of the current statement", "active"),
        new("SCRIPTS-RUNTIME-0011", "runtime", Severity.Error, "maximum call depth exceeded (10000) in `{function}`", "function and lambda calls (including callbacks of the standard library) are limited to 10 000 nested levels", "replace the recursion with a `while`/`for` loop", "the start of the statement that performs the excess call", "active"),
