        new("SCRIPTS-RUNTIME-0014", "runtime", Severity.Error, "list too long: {length} elements (maximum 268435456)", "a list would exceed 2^28 elements (concatenation, `append`, `lines`, `split`, `filesystem.list_directory`, …)", "process the data in chunks", "the start of the current statement", "active"),
