        new("SCRIPTS-CLI-0003", "cli", Severity.Error, "option `{option}` unknown or not accepted by `scripts {command}`", "nonexistent option, or option valid for another command (`--json-out` exists for `run` and `explain`; `--errors-json` is not accepted by `explain` or `describe`; a script whose name starts with `-` is read as an option; `-` alone is the standard input for `run` and `check` only, so `explain -` is this error)", "options accepted by `scripts {command}`: {accepted}; for a script starting with `-`, write `./-x.scs`", "none (no file)", "active"),
        new("SCRIPTS-CLI-0004", "cli", Severity.Error, "option `{option}` placed after the script: options precede the script", "the options accepted by the command must precede `<script.scs>` (`run`: `--errors-json`/`--json-out`; `check`: `--errors-json`/`--deny-warnings`/`--fix`; `explain`: `--json-out`); after the script path (up to a possible `--`) they are refused (S1) and not passed to the script; any other post-script argument is an argument of the script and is never refused", "write `scripts {command} {option} {script}`", "none (no file)", "active"),
        new("SCRIPTS-CLI-0005", "cli", Severity.Error, "missing script for `scripts {command}`", "`run`, `check`, `explain` and `fmt` require a script path", "`scripts {command} <script.scs>`", "none (no file)", "active"),
        new("SCRIPTS-CLI-0006", "cli", Severity.Error, "`scripts describe` requires `--format json` (received value: `{value}`)", "the `--format` option is absent, has no value, or its value is not `json`", "`scripts describe --format json`", "none (no file)", "active"),
        new("SCRIPTS-CLI-0007", "cli", Severity.Error, "unexpected extra argument: `{argument}`", "too many arguments (`check` and `explain` accept only one script; `--` exists only for `run`; `--version`, `--help` and `help` accept nothing else)", "remove `{argument}`; to pass arguments to the script: `scripts run script.scs -- argument?`", "none (no file)", "active"),
        new("SCRIPTS-CLI-0008", "cli", Severity.Error, "repeated option: `{option}`", "the same option is provided several times (conservative reading: ambiguity refused)", "provide the option only once", "none (no file)", "active"),
        new("SCRIPTS-CLI-0009", "cli", Severity.Error, "script not found or unreadable: `{path}` ({reason})", "the file does not exist, is a directory, is not a regular file (FIFO, socket or block device), is not readable or cannot be read; exit code 252 (and not 250)", "check the path and the permissions of `{path}`", "none (no file)", "active"),
        new("SCRIPTS-CLI-0010", "cli", Severity.Error, "cannot read the script from standard input ({reason})", "the script path is `-` (`scripts run -`, `scripts check -`) and that input cannot be read (for example it is a directory, or a read fails); a closed standard input is not this error, it is an empty script. Exit code 252 (and not 250)", "pipe a script into scripts (`scripts run - < script.scs`) or pass the script path instead of `-`", "none (no file)", "active"),
        new("SCRIPTS-CLI-0011", "cli", Severity.Error, "`--errors-json` and `--json-out` cannot be combined", "each command has one machine-readable output form: the two flags describe the same document differently, so accepting both would make the output ambiguous. Exit code 250", "keep one of the two flags", "the second flag", "active"),
