        new("SCRIPTS-LINT-0003", "lint", Severity.Warning, "the string contains a `$` followed by a name: scripts interpolation is `{…}`, not `$name`", "a `string` literal (not a raw string `r\"…\"`, nor a path literal `p\"…\"`) contains a `$` followed by an identifier character (the bash habit); scripts performs no variable expansion, so the `$` and the name are printed literally", "use `{…}` interpolation, or a raw string `r\"…\"` for text meant for another language", "the `$`", "active"),
